// =========================================================
// Adonay — Router de la SPA
// Intercambia el contenido de #viewRoot sin recargar la página.
//
// Las vistas de la app están
// incrustadas aquí mismo como strings (VIEWS_HTML más abajo) en
// vez de cargarse con fetch() desde views/*.html. Esto es
// intencional: fetch() de archivos locales NO funciona cuando la
// app se abre con doble clic (file:///...) — el navegador lo
// bloquea por seguridad — ni siempre de forma confiable dentro del
// WebView de Capacitor. Al incrustar el HTML directamente, la app
// funciona igual con doble clic, con Live Server, o empaquetada en
// Android con Capacitor, sin depender de un servidor.
//
// IMPORTANTE: si editas views/stock-view.html (o cualquier otra
// vista) en el futuro, ese cambio por sí solo NO se reflejará —
// hay que volver a copiar el HTML actualizado dentro del string
// correspondiente en VIEWS_HTML, más abajo en este mismo archivo.
// =========================================================

const VIEWS_HTML = {
  "dashboard": "<!-- ── Main: Dashboard ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Dashboard</h1>\n      <p>Resumen general del negocio</p>\n    </div>\n    <!-- Plan de la tienda (Básico/Medio/Premium) — lo pinta\n         renderPlanBadge() en dashboard-logic.js con nombrePlan() de\n         plan-limits.js. Vacío hasta que Dashboard.init() corre, para\n         no mostrar un plan incorrecto ni por un instante. -->\n    <span class=\"dash-plan-tag\" id=\"dashPlanTag\" style=\"display:none\"></span>\n  </div>\n\n  <div class=\"page-content\">\n\n    <div class=\"dash-stats\">\n      <div class=\"stat-card dash-stat-card dash-stat-hero\">\n        <div class=\"dash-stat-head\">\n          <span class=\"stat-label\">Valor de inventario</span>\n          <span class=\"dash-stat-icon dash-ic-teal\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M20 7H4a1 1 0 0 0-1 1v10a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V8a1 1 0 0 0-1-1z\"/><path d=\"M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2\"/></svg>\n          </span>\n        </div>\n        <div class=\"stat-value\" id=\"dashStockValue\">—</div>\n      </div>\n      <div class=\"stat-card dash-stat-card\">\n        <div class=\"dash-stat-head\">\n          <span class=\"stat-label\">Productos registrados</span>\n          <span class=\"dash-stat-icon dash-ic-copper\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M20.5 7.3 12 12l-8.5-4.7M12 12v9M3.5 7.3v9.4L12 21l8.5-4.3V7.3L12 3z\"/></svg>\n          </span>\n        </div>\n        <div class=\"stat-value\" id=\"dashProductCount\">—</div>\n      </div>\n      <div class=\"stat-card dash-stat-card dash-stat-risk\">\n        <div class=\"dash-stat-head\">\n          <span class=\"stat-label\">Stock bajo</span>\n          <span class=\"dash-stat-icon dash-ic-red\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n          </span>\n        </div>\n        <div class=\"stat-value\" style=\"color:var(--red)\" id=\"dashLowStock\">—</div>\n      </div>\n      <!-- Clientes: solo tiene sentido en planes con Pedidos habilitado\n           (Medio/Premium — ver limitePlan('pedidosDisponible') en\n           plan-limits.js). Básico no gestiona clientes en ningún lado\n           de la app (Pedidos/Registros ya están ocultos en su sidebar,\n           ver index.html), así que esta tarjeta tampoco se le muestra.\n           dashboard-logic.js la oculta/muestra en init(). -->\n      <div class=\"stat-card dash-stat-card\" id=\"dashClientCard\">\n        <div class=\"dash-stat-head\">\n          <span class=\"stat-label\">Clientes registrados</span>\n          <span class=\"dash-stat-icon dash-ic-amber\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n          </span>\n        </div>\n        <div class=\"stat-value\" id=\"dashClientCount\">—</div>\n      </div>\n    </div>\n\n    <div class=\"dash-charts\">\n\n      <div class=\"dash-panel dash-panel-chart\">\n        <div class=\"dash-panel-header\">\n          <h2>Stock por almacén</h2>\n          <span class=\"dash-panel-metric\" id=\"dashWarehouseUnitsTotal\">—</span>\n        </div>\n        <div id=\"dashWarehouseUnitsList\" class=\"dash-wh-value-list\">\n          <p class=\"dash-empty\">Cargando…</p>\n        </div>\n      </div>\n\n      <div class=\"dash-panel dash-panel-chart\">\n        <div class=\"dash-panel-header\">\n          <h2>Stock por categoría</h2>\n          <span class=\"dash-panel-metric\" id=\"dashCategoryUnitsTotal\">—</span>\n        </div>\n        <div class=\"dash-chart-wrap dash-donut-wrap\">\n          <canvas id=\"chartCategories\"></canvas>\n          <div class=\"dash-donut-center\">\n            <div class=\"dash-donut-center-value\" id=\"dashCategoryDonutTotal\">—</div>\n            <div class=\"dash-donut-center-label\">unidades</div>\n          </div>\n        </div>\n        <div id=\"chartCategoriesLegend\" class=\"dash-legend\"></div>\n      </div>\n\n    </div>\n\n    <div class=\"dash-grid\">\n\n      <div class=\"dash-panel\">\n        <div class=\"dash-panel-header\">\n          <h2>Stock bajo</h2>\n          <a href=\"#stock\" class=\"dash-panel-link\">Ver inventario</a>\n        </div>\n        <div id=\"dashLowStockList\" class=\"dash-list\">\n          <p class=\"dash-empty\">Cargando…</p>\n        </div>\n      </div>\n\n      <!-- Rentabilidad: solo planes Medio/Premium (los que ven costo en\n           Stock — mismo limitePlan('campoCosto') de plan-limits.js, no\n           un flag nuevo). Básico no ve costo en ningún lado de la app,\n           así que este panel ni siquiera existe para él: queda oculto\n           por defecto y dashboard-logic.js lo muestra solo si aplica. -->\n      <div class=\"dash-panel\" id=\"dashProfitPanel\" style=\"display:none\">\n        <div class=\"dash-panel-header\">\n          <h2>Rentabilidad de inventario</h2>\n          <span class=\"dash-plan-badge\">Medio · Premium</span>\n        </div>\n        <div class=\"dash-profit-summary\">\n          <div class=\"dash-profit-item\">\n            <div class=\"dash-profit-label\">Costo total</div>\n            <div class=\"dash-profit-value\" id=\"dashCostTotal\">—</div>\n          </div>\n          <div class=\"dash-profit-item\">\n            <div class=\"dash-profit-label\">Margen estimado</div>\n            <div class=\"dash-profit-value\" id=\"dashMarginTotal\">—</div>\n          </div>\n          <div class=\"dash-profit-item\">\n            <div class=\"dash-profit-label\">Margen</div>\n            <div class=\"dash-profit-value\" id=\"dashMarginPct\">—</div>\n          </div>\n        </div>\n        <div class=\"dash-panel-header\" style=\"margin-top:14px\">\n          <h2 style=\"font-size:12.5px;color:var(--text-3)\">Mayor margen unitario</h2>\n        </div>\n        <div id=\"dashTopMarginList\" class=\"dash-list\">\n          <p class=\"dash-empty\">Cargando…</p>\n        </div>\n      </div>\n\n    </div>\n\n    <!-- ── Panel avanzado (exclusivo Premium) ──────────────────\n         Tres análisis que solo tienen sentido con volumen real de\n         datos: concentración de valor (ABC/Pareto), comparación de\n         valor entre almacenes (hasta 6 solo en Premium) e índice de\n         salud de inventario. renderAdvancedPanel() en\n         dashboard-logic.js SIEMPRE calcula y pinta estos tres con\n         datos reales de la tienda — en Básico/Medio el mismo bloque\n         queda con blur + candado encima (dashAdvancedLock), no un\n         placeholder de mentira, para que quede claro que es la\n         propia información de la tienda la que se desbloquea al\n         subir de plan. -->\n    <div class=\"dash-advanced-section\" id=\"dashAdvancedSection\">\n      <div class=\"dash-advanced-header\">\n        <div class=\"dash-advanced-eyebrow\">\n          <svg viewBox=\"0 0 24 24\" class=\"dash-crown-icon\"><path d=\"M5 18h14l1.6-9.4-5.1 3-3.5-6.1-3.5 6.1-5.1-3L5 18z\"/><path d=\"M5 18h14\"/></svg>\n          Panel avanzado · Premium\n        </div>\n        <h2 class=\"dash-advanced-title\">Análisis inteligente de tu inventario</h2>\n        <p class=\"dash-advanced-sub\">Lo que ves acá se calcula con los datos reales de tu tienda — no es una demostración.</p>\n      </div>\n\n      <div class=\"dash-advanced-body\" id=\"dashAdvancedBody\">\n        <div class=\"dash-advanced-grid\" id=\"dashAdvancedGrid\">\n\n          <!-- Anillos de progreso — 3 indicadores clave de un vistazo,\n               el mismo lenguaje visual que un panel de BI real. -->\n          <div class=\"dash-ring-row\">\n            <div class=\"dash-ring-card\">\n              <div class=\"dash-ring-wrap\">\n                <canvas id=\"chartRingDisponibilidad\"></canvas>\n                <div class=\"dash-ring-value\" id=\"ringDisponibilidadVal\">—</div>\n              </div>\n              <div class=\"dash-ring-label\">Disponibilidad de stock</div>\n            </div>\n            <div class=\"dash-ring-card\">\n              <div class=\"dash-ring-wrap\">\n                <canvas id=\"chartRingDiversificacion\"></canvas>\n                <div class=\"dash-ring-value\" id=\"ringDiversificacionVal\">—</div>\n              </div>\n              <div class=\"dash-ring-label\">Diversificación de categorías</div>\n            </div>\n            <div class=\"dash-ring-card\">\n              <div class=\"dash-ring-wrap\">\n                <canvas id=\"chartRingCostos\"></canvas>\n                <div class=\"dash-ring-value\" id=\"ringCostosVal\">—</div>\n              </div>\n              <div class=\"dash-ring-label\">Cobertura de costos cargados</div>\n            </div>\n          </div>\n\n          <div class=\"dash-advanced-row-3col\">\n\n            <div class=\"dash-panel dash-panel-abc\">\n              <div class=\"dash-panel-header\">\n                <h2>Concentración de valor (ABC)</h2>\n                <span class=\"dash-plan-badge dash-plan-badge-premium\">Premium</span>\n              </div>\n              <p class=\"dash-abc-summary\" id=\"dashAbcSummary\">Cargando…</p>\n              <div class=\"dash-chart-wrap dash-chart-wrap-sm\">\n                <canvas id=\"chartAbc\"></canvas>\n              </div>\n              <div id=\"dashAbcLegend\" class=\"dash-legend dash-abc-legend\"></div>\n              <div id=\"dashAbcList\" class=\"dash-list\"></div>\n            </div>\n\n            <div class=\"dash-panel dash-panel-wh-value\">\n              <div class=\"dash-panel-header\">\n                <h2>Valor por almacén</h2>\n                <span class=\"dash-plan-badge dash-plan-badge-premium\">Premium</span>\n              </div>\n              <div id=\"dashWarehouseValueList\" class=\"dash-wh-value-list\">\n                <p class=\"dash-empty\">Cargando…</p>\n              </div>\n            </div>\n\n            <div class=\"dash-panel dash-panel-health\">\n              <div class=\"dash-panel-header\">\n                <h2>Índice de salud del inventario</h2>\n                <span class=\"dash-plan-badge dash-plan-badge-premium\">Premium</span>\n              </div>\n              <div class=\"dash-health-wrap\">\n                <div class=\"dash-gauge-wrap\">\n                  <canvas id=\"chartHealth\"></canvas>\n                  <div class=\"dash-gauge-score\">\n                    <span id=\"dashHealthScore\">—</span>\n                    <span class=\"dash-gauge-score-label\">/ 100</span>\n                  </div>\n                </div>\n                <div class=\"dash-health-breakdown\" id=\"dashHealthBreakdown\"></div>\n              </div>\n            </div>\n\n          </div>\n\n          <div class=\"dash-advanced-row-2col\">\n\n            <div class=\"dash-panel dash-panel-radar\">\n              <div class=\"dash-panel-header\">\n                <h2>Comparativa entre almacenes</h2>\n                <span class=\"dash-plan-badge dash-plan-badge-premium\">Premium</span>\n              </div>\n              <div class=\"dash-chart-wrap dash-chart-wrap-radar\" id=\"dashRadarWrap\">\n                <canvas id=\"chartWarehouseRadar\"></canvas>\n              </div>\n              <div id=\"dashRadarLegend\" class=\"dash-legend\"></div>\n            </div>\n\n            <div class=\"dash-panel dash-panel-insights\">\n              <div class=\"dash-panel-header\">\n                <h2>Insights inteligentes</h2>\n                <span class=\"dash-plan-badge dash-plan-badge-premium\">Premium</span>\n              </div>\n              <div id=\"dashInsightsList\" class=\"dash-insights-list\">\n                <p class=\"dash-empty\">Cargando…</p>\n              </div>\n            </div>\n\n          </div>\n\n        </div>\n\n        <div class=\"dash-advanced-lock\" id=\"dashAdvancedLock\" style=\"display:none\">\n          <div class=\"dash-lock-icon-wrap\">\n            <svg viewBox=\"0 0 24 24\" class=\"dash-lock-icon\"><rect x=\"5\" y=\"11\" width=\"14\" height=\"9\" rx=\"2\"/><path d=\"M8 11V7a4 4 0 0 1 8 0v4\"/></svg>\n          </div>\n          <p class=\"dash-lock-title\">Disponible en el plan Premium</p>\n          <p class=\"dash-lock-text\">Análisis ABC, valor por almacén, comparativa entre almacenes e insights automáticos, calculados con los datos reales de tu tienda. Pídele a tu proveedor que suba tu plan para verlos nítidos.</p>\n        </div>\n\n      </div>\n    </div>\n\n  </div>\n</main>",
  "stock": "<!-- ── Main: Stock ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Stock</h1>\n      <p>Cantidades, códigos y precios</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <div class=\"search-wrap\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <input type=\"text\" id=\"searchInput\" placeholder=\"Buscar producto o código…\" oninput=\"filterStock()\">\n      </div>\n      <button class=\"btn btn-ghost btn-select\" id=\"btnSelectMode\" onclick=\"toggleSelectionMode()\" title=\"Seleccionar varios\">\n        <svg viewBox=\"0 0 24 24\"><polyline points=\"9 11 12 14 22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n        <span id=\"selectModeLabel\">Seleccionar</span>\n      </button>\n      <div class=\"import-menu-wrap\" id=\"importMenuWrap\">\n        <button class=\"btn-import\" id=\"btnImportMenu\" onclick=\"toggleImportMenu(event)\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n          Importar\n        </button>\n        <div class=\"import-menu\" id=\"importMenuDropdown\">\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('full')\">\n            <strong>Importar todo</strong>\n            <span>Código, nombre, descripción, cantidad y precio — crea nuevos y actualiza existentes</span>\n          </button>\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('both')\">\n            <strong>Cantidad y precio</strong>\n            <span>Suma la cantidad y reemplaza el precio en productos que ya existen</span>\n          </button>\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('stock')\">\n            <strong>Solo cantidad</strong>\n            <span>Suma la cantidad al stock de productos que ya existen</span>\n          </button>\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('price')\">\n            <strong>Solo precio</strong>\n            <span>Reemplaza el precio de productos que ya existen</span>\n          </button>\n        </div>\n      </div>\n      <button class=\"btn btn-ghost\" id=\"btnExportStock\" onclick=\"exportStock()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n        <span id=\"exportStockLabel\">Exportar todo</span>\n      </button>\n\n      <!-- Import/export de UN almacén — solo visible con un almacén\n           seleccionado (ver switchWarehouse en stock.js) -->\n      <button class=\"btn btn-ghost\" id=\"btnImportWarehouse\" style=\"display:none\" onclick=\"openWarehouseImport()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n        Importar cantidad\n      </button>\n      <button class=\"btn btn-ghost\" id=\"btnExportWarehouse\" style=\"display:none\" onclick=\"exportWarehouseStock()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n        Exportar\n      </button>\n\n      <button class=\"btn btn-primary btn-new-item\" id=\"btnAddProductTop\" onclick=\"openAddModal()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\n        Agregar producto\n      </button>\n    </div>\n  </div>\n\n  <!-- Botón flotante \"+\" — reemplaza a \"Agregar producto\" solo en\n       móvil (ver @media max-width:768px en base.css), donde ese\n       botón fijo le comía espacio al encabezado. En escritorio\n       queda oculto y se usa el botón de arriba, sin cambios. -->\n  <button class=\"fab-add\" id=\"fabAddProduct\" onclick=\"openAddModal()\" title=\"Agregar producto\">\n    <svg viewBox=\"0 0 24 24\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\n  </button>\n\n  <!-- Pestañas de almacén: \"Todos\" y Almacén 1 son fijas (alm1 nunca\n       se puede desactivar). De alm2 en adelante (hasta 6, según plan)\n       se generan al vuelo en aplicarConfigAlmacenes() — ver stock.js. -->\n  <div class=\"warehouse-tabs\" id=\"warehouseTabs\">\n    <button class=\"warehouse-tab active\" data-wh=\"\" onclick=\"switchWarehouse('')\">Todos los almacenes</button>\n    <button class=\"warehouse-tab\" data-wh=\"alm1\" onclick=\"switchWarehouse('alm1')\">Almacén 1</button>\n  </div>\n\n  <div class=\"page-content\">\n\n    <!-- Stats -->\n    <div class=\"stock-stats\" id=\"stockStatsRow\">\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Total productos</div>\n        <div class=\"stat-value\" id=\"statTotal\">—</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Stock bajo</div>\n        <div class=\"stat-value\" style=\"color:var(--red)\" id=\"statLow\">—</div>\n      </div>\n      <div class=\"stat-card\" id=\"cardValorInventario\">\n        <div class=\"stat-label\">Valor inventario</div>\n        <div class=\"stat-value\" id=\"statValue\">—</div>\n      </div>\n    </div>\n\n    <!-- Barra de acciones masivas -->\n    <div class=\"bulk-bar\" id=\"bulkBarStock\">\n      <span class=\"bulk-count\" id=\"bulkCountStock\">0 seleccionados</span>\n      <button class=\"btn-bulk-delete\" onclick=\"deleteSelectedStock()\">\n        <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n        Eliminar seleccionados\n      </button>\n      <button class=\"btn-bulk-select-all\" onclick=\"selectAllStock()\">Seleccionar todo</button>\n    </div>\n\n    <!-- Lista de productos (cards, vista mobile) -->\n    <div class=\"product-list\" id=\"productList\"></div>\n\n    <!-- Tabla de productos (vista desktop) -->\n    <div class=\"product-table-wrap\">\n      <table class=\"product-table\">\n        <thead>\n          <tr>\n            <th class=\"col-check\"><input type=\"checkbox\" class=\"row-checkbox\" id=\"checkAllStock\" onchange=\"toggleAllStock(this)\"></th>\n            <th class=\"col-img\">Img</th>\n            <th>Código</th>\n            <th>Nombre</th>\n            <th id=\"colStockHeader\">Cantidad</th>\n            <th>Precio venta</th>\n            <th></th>\n          </tr>\n        </thead>\n        <tbody id=\"productTableBody\"></tbody>\n      </table>\n    </div>\n\n    <div class=\"empty-state\" id=\"emptyState\" style=\"display:none\">\n      <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n      <p>Sin productos que coincidan.</p>\n    </div>\n    <div class=\"table-footer\">\n      <span class=\"table-footer-text\" id=\"footerInfo\">Cargando…</span>\n    </div>\n\n  </div>\n</main>\n\n<!-- ── Modal: Editar ── -->\n<div class=\"modal-overlay\" id=\"editModal\" onclick=\"outsideClose(event,'editModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"editModalTitle\">Editar producto</h2>\n        <p id=\"editModalCode\" style=\"font-family:var(--font-mono);font-size:12px;color:var(--text-3);margin-top:3px\"></p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('editModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Código</label>\n        <input class=\"form-input text-mono\" id=\"editCode\" type=\"text\"\n          oninput=\"this.value=this.value.toUpperCase()\" style=\"text-transform:uppercase\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre del producto <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(renombrar)</span></label>\n        <input class=\"form-input\" id=\"editName\" type=\"text\">\n      </div>\n      <!-- Descripción desactivada temporalmente (a pedido) — se\n           conserva la que ya tenía cada producto, solo no se ve/edita\n           aquí. Para reactivarla, quitar el display:none. -->\n      <div class=\"form-group\" style=\"display:none\">\n        <label class=\"form-label\">Descripción <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <textarea class=\"form-input\" id=\"editDesc\" rows=\"2\" style=\"resize:vertical\" placeholder=\"Detalle adicional del producto\"></textarea>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Imagen del producto <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <div class=\"product-image-picker\">\n          <div class=\"product-image-preview\" id=\"editImagePreview\">\n            <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"/><polyline points=\"21 15 16 10 5 21\"/></svg>\n          </div>\n          <div>\n            <label class=\"btn btn-ghost btn-sm\" for=\"editImageFile\">Cambiar imagen</label>\n            <input type=\"file\" id=\"editImageFile\" accept=\"image/*\" style=\"display:none\" onchange=\"previewProductImage(this,'editImagePreview','edit')\">\n            <p style=\"font-size:11.5px;color:var(--text-3);margin-top:4px\">JPG o PNG. Se sube automáticamente al elegirla.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label class=\"form-label\" id=\"editStockLabel\">Cantidad</label>\n          <input class=\"form-input text-mono\" id=\"editStock\" type=\"number\" min=\"0\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Moneda</label>\n          <select class=\"form-input\" id=\"editCurrency\">\n            <option value=\"PEN\">Soles (S/)</option>\n            <option value=\"USD\">Dólares ($)</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"form-group\" id=\"editCostoGroup\" style=\"display:none\">\n        <label class=\"form-label\">Costo</label>\n        <input class=\"form-input text-mono\" id=\"editCosto\" type=\"number\" min=\"0\" step=\"0.01\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\" id=\"editPriceLabel\">Precio</label>\n        <input class=\"form-input text-mono\" id=\"editPrice\" type=\"number\" min=\"0\" step=\"0.01\">\n      </div>\n      <div class=\"form-group\" id=\"editPrecioMayorGroup\" style=\"display:none\">\n        <label class=\"form-label\">Precio mayor</label>\n        <input class=\"form-input text-mono\" id=\"editPrecioMayor\" type=\"number\" min=\"0\" step=\"0.01\">\n      </div>\n    </div>\n    <div class=\"modal-footer\" style=\"justify-content:space-between\">\n      <button class=\"btn btn-ghost\" id=\"btnDeleteProduct\" style=\"color:var(--red);border-color:#FECACA\" onclick=\"deleteCurrentProduct()\">Eliminar producto</button>\n      <div style=\"display:flex;gap:8px\">\n        <button class=\"btn btn-ghost\" onclick=\"closeModal('editModal')\">Cancelar</button>\n        <button class=\"btn btn-primary\" onclick=\"saveStock()\">Guardar cambios</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Agregar ── -->\n<div class=\"modal-overlay\" id=\"addModal\" onclick=\"outsideClose(event,'addModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Nuevo producto</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\">Registrar en inventario</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('addModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Código</label>\n        <input class=\"form-input text-mono\" id=\"addCode\" type=\"text\" placeholder=\"GTR-006\"\n          oninput=\"this.value=this.value.toUpperCase()\" style=\"text-transform:uppercase\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre del producto</label>\n        <input class=\"form-input\" id=\"addName\" type=\"text\" placeholder=\"Ej: Guitarra Yamaha C40\">\n      </div>\n      <!-- Descripción desactivada temporalmente (a pedido) — para\n           reactivarla, quitar el display:none. -->\n      <div class=\"form-group\" style=\"display:none\">\n        <label class=\"form-label\">Descripción <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <textarea class=\"form-input\" id=\"addDesc\" rows=\"2\" style=\"resize:vertical\" placeholder=\"Detalle adicional del producto\"></textarea>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Imagen del producto <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <div class=\"product-image-picker\">\n          <div class=\"product-image-preview\" id=\"addImagePreview\">\n            <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"/><polyline points=\"21 15 16 10 5 21\"/></svg>\n          </div>\n          <div>\n            <label class=\"btn btn-ghost btn-sm\" for=\"addImageFile\">Subir imagen</label>\n            <input type=\"file\" id=\"addImageFile\" accept=\"image/*\" style=\"display:none\" onchange=\"previewProductImage(this,'addImagePreview','add')\">\n            <p style=\"font-size:11.5px;color:var(--text-3);margin-top:4px\">JPG o PNG. Se sube automáticamente al elegirla.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Cantidad</label>\n        <input class=\"form-input text-mono\" id=\"addStock\" type=\"number\" min=\"0\" placeholder=\"0\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Moneda</label>\n        <select class=\"form-input\" id=\"addCurrency\">\n          <option value=\"PEN\">Soles (S/)</option>\n          <option value=\"USD\">Dólares ($)</option>\n        </select>\n      </div>\n      <div class=\"form-group\" id=\"addCostoGroup\" style=\"display:none\">\n        <label class=\"form-label\">Costo</label>\n        <input class=\"form-input text-mono\" id=\"addCosto\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"0.00\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\" id=\"addPriceLabel\">Precio</label>\n        <input class=\"form-input text-mono\" id=\"addPrice\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"0.00\">\n      </div>\n      <div class=\"form-group\" id=\"addPrecioMayorGroup\" style=\"display:none\">\n        <label class=\"form-label\">Precio mayor</label>\n        <input class=\"form-input text-mono\" id=\"addPrecioMayor\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"0.00\">\n      </div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('addModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" onclick=\"addProduct()\">Registrar producto</button>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Importar stock ── -->\n<!-- ── Modal: Ver imagen ── -->\n<div class=\"modal-overlay\" id=\"imageViewModal\" onclick=\"outsideClose(event,'imageViewModal')\">\n  <div class=\"modal\" style=\"max-width:420px\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"imageViewName\">Imagen</h2>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('imageViewModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" style=\"text-align:center\">\n      <img id=\"imageViewImg\" src=\"\" alt=\"\" style=\"max-width:100%;max-height:60vh;border-radius:var(--r-md);object-fit:contain\">\n    </div>\n    <div class=\"modal-footer\" style=\"justify-content:flex-end\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('imageViewModal')\">Cerrar</button>\n      <button class=\"btn btn-ghost\" id=\"imageViewShare\" style=\"display:none\" onclick=\"compartirImagenActual()\">Compartir</button>\n      <a class=\"btn btn-primary\" id=\"imageViewDownload\" href=\"\" target=\"_blank\" rel=\"noopener\">Descargar</a>\n    </div>\n  </div>\n</div>\n\n<div class=\"modal-overlay\" id=\"importStockModal\" onclick=\"if(event.target===this)closeImportStock()\">\n  <div class=\"modal import-modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"importStockModalTitle\">Importar productos</h2>\n        <p id=\"importStockModalHint\" style=\"font-size:12px;color:var(--text-3);margin-top:3px\"></p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeImportStock()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n\n      <!-- Paso 1 -->\n      <div id=\"stepUploadStock\">\n        <!-- Selector de almacén destino: solo aparece si el modo mueve\n             cantidad (no en \"Solo precio\") Y la tienda tiene más de un\n             almacén activo — con uno solo no hay nada que preguntar,\n             se importa ahí directo (ver populateImportWarehousePicker\n             en import-stock.js). -->\n        <div class=\"form-group\" id=\"importWarehousePicker\" style=\"display:none\">\n          <label class=\"form-label\">¿En qué almacén se guarda?</label>\n          <select class=\"form-input\" id=\"importWarehouseSelect\" onchange=\"onImportWarehouseChange(this)\"></select>\n          <p style=\"font-size:11.5px;color:var(--text-3);margin-top:4px\">La cantidad del archivo se guarda en el almacén que elijas acá.</p>\n        </div>\n        <div class=\"import-template-bar\">\n          <span>¿Primera vez? Descarga la plantilla con el formato correcto para esta opción.</span>\n          <button class=\"btn-template\" onclick=\"downloadStockTemplate()\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n            Descargar plantilla\n          </button>\n        </div>\n        <label class=\"import-drop-area\" for=\"importStockFile\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n          <p>Arrastra tu archivo aquí o <strong>haz clic para seleccionar</strong></p>\n          <p style=\"margin-top:6px;font-size:11.5px\" id=\"importStockDropHint\">Excel (.xlsx) o CSV</p>\n        </label>\n        <input type=\"file\" id=\"importStockFile\" class=\"import-file-input\"\n          accept=\".xlsx,.xls,.csv\" onchange=\"onImportStockFile(this)\">\n        <div id=\"importStockError\" style=\"display:none;margin-top:12px;padding:10px 14px;background:var(--red-bg);border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:var(--red)\"></div>\n      </div>\n\n      <!-- Paso 2: Preview -->\n      <div id=\"stepPreviewStock\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"previewStockSummary\"></p>\n        <p id=\"previewStockSanitizedWarning\" style=\"display:none;margin:0 0 10px;padding:8px 12px;background:var(--yellow-bg,#FEF3C7);border:1px solid #FDE68A;border-radius:var(--r-sm);font-size:12px;color:#92400E\"></p>\n        <div class=\"import-preview-wrap\">\n          <div id=\"previewStockBody\"></div>\n        </div>\n      </div>\n\n      <!-- Paso 3: Conflictos de código (solo si hay) -->\n      <div id=\"stepConflictStock\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"conflictStockSummary\"></p>\n        <p id=\"conflictStockExplain\" style=\"display:none;margin:0 0 12px;padding:10px 14px;background:#FEE2E2;border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:#7F1D1D;line-height:1.5\"></p>\n        <div id=\"conflictStockBody\"></div>\n      </div>\n\n      <!-- Paso 4: Listo -->\n      <div id=\"stepDoneStock\" style=\"display:none\">\n        <div class=\"import-done\">\n          <div class=\"import-done-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n          <p id=\"importStockDoneMsg\"></p>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" id=\"btnCerrarImportStock\" onclick=\"closeImportStock()\">Cerrar</button>\n      <button class=\"btn btn-primary\" id=\"btnSiguienteImportStock\" onclick=\"goToConflictStep()\" style=\"display:none\">Siguiente</button>\n      <button class=\"btn btn-primary\" id=\"btnProcesarImportStock\" onclick=\"processImportStock()\" style=\"display:none\">Procesar importación</button>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Editar cantidad de UN almacén ── -->\n<div class=\"modal-overlay\" id=\"warehouseQtyModal\" onclick=\"outsideClose(event,'warehouseQtyModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"whQtyModalTitle\">Editar cantidad</h2>\n        <p id=\"whQtyModalWarehouse\" style=\"font-size:12px;color:var(--text-3);margin-top:3px\"></p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('warehouseQtyModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Cantidad en este almacén</label>\n        <input class=\"form-input text-mono\" id=\"whQtyInput\" type=\"number\" min=\"0\">\n      </div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('warehouseQtyModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" onclick=\"saveWarehouseQty()\">Guardar cambios</button>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Importar cantidad de UN almacén ── -->\n<div class=\"modal-overlay\" id=\"warehouseImportModal\" onclick=\"outsideClose(event,'warehouseImportModal')\">\n  <div class=\"modal import-modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"whImportModalTitle\">Importar cantidad</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:3px\">Suma la cantidad importada al stock actual de ese almacén, en productos que ya existen. No crea productos nuevos ni toca el precio.</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('warehouseImportModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"import-template-bar\">\n        <span>¿Primera vez? Descarga la plantilla con el formato correcto.</span>\n        <button class=\"btn-template\" onclick=\"downloadWarehouseTemplate()\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n          Descargar plantilla\n        </button>\n      </div>\n      <label class=\"import-drop-area\" for=\"warehouseImportFile\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n        <p>Arrastra tu archivo aquí o <strong>haz clic para seleccionar</strong></p>\n        <p style=\"margin-top:6px;font-size:11.5px\">Excel (.xlsx) o CSV con columnas: Código, Cantidad</p>\n      </label>\n      <input type=\"file\" id=\"warehouseImportFile\" class=\"import-file-input\"\n        accept=\".xlsx,.xls,.csv\" onchange=\"onWarehouseImportFile(this)\">\n      <div id=\"warehouseImportProgress\" style=\"display:none;margin-top:12px;font-size:12.5px;color:var(--text-3)\">Procesando…</div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('warehouseImportModal')\">Cerrar</button>\n    </div>\n  </div>\n</div>\n",
  "catalogo": "<!-- ── Main: Catálogo (galería de imágenes) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Catálogo</h1>\n      <p>Galería de imágenes de productos</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <div class=\"search-wrap\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <input type=\"text\" id=\"catalogoSearchInput\" placeholder=\"Buscar producto o código…\" oninput=\"filterCatalogo()\">\n      </div>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n\n    <div class=\"catalogo-grid\" id=\"catalogoGrid\"></div>\n\n    <div class=\"empty-state\" id=\"catalogoEmptyState\" style=\"display:none\">\n      <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n      <p>Sin productos que coincidan.</p>\n    </div>\n    <div class=\"table-footer\">\n      <span class=\"table-footer-text\" id=\"catalogoFooterInfo\">Cargando…</span>\n    </div>\n\n  </div>\n</main>\n\n<!-- ── Modal: Ver imagen ── -->\n<!-- Misma modal que usa Stock (mismos ids) — openImageView() en\n     stock.js es una función global compartida por toda la SPA, así\n     que solo hace falta que el HTML del modal exista en la vista\n     que está montada en cada momento (ver router.js: una sola vista\n     vive en #viewRoot a la vez). -->\n<div class=\"modal-overlay\" id=\"imageViewModal\" onclick=\"outsideClose(event,'imageViewModal')\">\n  <div class=\"modal\" style=\"max-width:420px\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"imageViewName\">Imagen</h2>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('imageViewModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" style=\"text-align:center\">\n      <img id=\"imageViewImg\" src=\"\" alt=\"\" style=\"max-width:100%;max-height:60vh;border-radius:var(--r-md);object-fit:contain\">\n    </div>\n    <div class=\"modal-footer\" style=\"justify-content:flex-end\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('imageViewModal')\">Cerrar</button>\n      <button class=\"btn btn-ghost\" id=\"imageViewShare\" style=\"display:none\" onclick=\"compartirImagenActual()\">Compartir</button>\n      <a class=\"btn btn-primary\" id=\"imageViewDownload\" href=\"\" target=\"_blank\" rel=\"noopener\">Descargar</a>\n    </div>\n  </div>\n</div>\n",
  "foro": "<!-- ── Main: Foro entre tiendas ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Foro entre tiendas</h1>\n      <p>Publica o busca productos de otras tiendas — vendo/busco por categoría.</p>\n    </div>\n    <button class=\"btn btn-primary\" onclick=\"abrirNuevaPublicacionForo()\">+ Nueva publicación</button>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"warehouse-tabs\" id=\"foroCategoriaTabs\">\n      <button class=\"warehouse-tab active\" data-cat=\"\" onclick=\"filtrarForoCategoria('')\">Todas</button>\n    </div>\n\n    <div id=\"foroLista\" class=\"catalogo-grid\"></div>\n    <div id=\"foroEmpty\" style=\"display:none;text-align:center;padding:40px 20px;color:var(--text-3);font-size:13px\">\n      Todavía no hay publicaciones en esta categoría.\n    </div>\n  </div>\n</main>\n\n<!-- ── Modal: nueva publicación ── -->\n<div class=\"modal-overlay\" id=\"foroModal\" onclick=\"outsideClose(event,'foroModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Nueva publicación</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\">Se publica a nombre de tu tienda, visible para las demás</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('foroModal')\">&times;</button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Tipo</label>\n        <select class=\"form-input\" id=\"foroTipo\">\n          <option value=\"vendo\">Vendo</option>\n          <option value=\"busco\">Busco</option>\n        </select>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Categoría</label>\n        <select class=\"form-input\" id=\"foroCategoria\"></select>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Título</label>\n        <input class=\"form-input\" id=\"foroTitulo\" type=\"text\" maxlength=\"80\" placeholder=\"Ej: Guitarra Fender Stratocaster\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Precio (opcional)</label>\n        <input class=\"form-input text-mono\" id=\"foroPrecio\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"0.00\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Descripción</label>\n        <textarea class=\"form-input\" id=\"foroDescripcion\" rows=\"4\" maxlength=\"500\" placeholder=\"Detalles, estado, forma de contacto...\"></textarea>\n      </div>\n      <p id=\"foroModalMsg\" class=\"settings-msg\"></p>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('foroModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" id=\"btnPublicarForo\" onclick=\"enviarPublicacionForo()\">Publicar</button>\n    </div>\n  </div>\n</div>\n",
  "pedidos": "<!-- ── Main: Notas de Pedido ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Notas de Pedido</h1>\n      <p>Gestión de órdenes de clientes</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <div class=\"search-wrap\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <input type=\"text\" id=\"searchInput\" placeholder=\"RUC o razón social…\" oninput=\"filterTable()\">\n      </div>\n      <button class=\"btn btn-ghost btn-select\" id=\"btnSelectMode\" onclick=\"toggleClienteSelectionMode()\" title=\"Seleccionar varios\">\n        <svg viewBox=\"0 0 24 24\"><polyline points=\"9 11 12 14 22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n        <span id=\"selectModeLabel\">Seleccionar</span>\n      </button>\n      <button class=\"btn-import\" onclick=\"openImportClientes()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n        Importar\n      </button>\n      <button class=\"btn btn-ghost\" id=\"btnExportClientes\" onclick=\"exportClientes()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n        <span id=\"exportClientesLabel\">Exportar todo</span>\n      </button>\n      <button class=\"btn btn-ghost btn-new-item\" onclick=\"openNewClient()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><line x1=\"19\" y1=\"8\" x2=\"19\" y2=\"14\"/><line x1=\"22\" y1=\"11\" x2=\"16\" y2=\"11\"/></svg>\n        Nuevo cliente\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <!-- Barra de acciones masivas -->\n    <div class=\"bulk-bar\" id=\"bulkBarClientes\">\n      <span class=\"bulk-count\" id=\"bulkCountClientes\">0 seleccionados</span>\n      <button class=\"btn-bulk-delete\" onclick=\"deleteSelectedClientes()\">\n        <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n        Eliminar seleccionados\n      </button>\n      <button class=\"btn-bulk-select-all\" onclick=\"selectAllClientes()\">Seleccionar todo</button>\n    </div>\n\n    <div class=\"table-wrap\">\n      <div class=\"table-footer table-footer-top\">\n        <span class=\"table-footer-text\" id=\"footerInfo\">Cargando…</span>\n      </div>\n      <table>\n        <thead>\n          <tr>\n            <th class=\"col-check\"><input type=\"checkbox\" class=\"row-checkbox\" id=\"checkAllClientes\" onchange=\"toggleAllClientes(this)\"></th>\n            <th class=\"col-ruc\">RUC</th>\n            <th>Cliente</th>\n            <th class=\"col-city\">Ciudad</th>\n            <th class=\"col-acts\">Acciones</th>\n          </tr>\n        </thead>\n        <tbody id=\"tableBody\">\n        </tbody>\n      </table>\n      <div class=\"empty-state\" id=\"emptyState\">\n        <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <p>Sin resultados para esa búsqueda.</p>\n      </div>\n    </div>\n  </div>\n</main>\n\n<!-- ── Modal: Editar cliente ─── -->\n<div class=\"modal-overlay\" id=\"editModal\" onclick=\"outsideCloseCliente(event)\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"editModalTitle\">Editar cliente</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\" id=\"editModalSubtitle\">Modificar datos del cliente en la nota</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeEdit()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"modal-detail-row\" id=\"editCurrentInfo\">\n        <div class=\"modal-detail-item\">\n          <div class=\"modal-detail-label\">RUC actual</div>\n          <div class=\"modal-detail-value\" id=\"editCurrentRuc\">—</div>\n        </div>\n        <div class=\"modal-detail-item\">\n          <div class=\"modal-detail-label\">Ciudad</div>\n          <div class=\"modal-detail-value\" id=\"editCurrentCity\">—</div>\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">RUC</label>\n        <input class=\"form-input text-mono\" id=\"editRuc\" type=\"text\" maxlength=\"11\" placeholder=\"20xxxxxxxxx\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Razón social</label>\n        <input class=\"form-input\" id=\"editNombre\" type=\"text\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Ciudad <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <input class=\"form-input\" id=\"editCiudad\" type=\"text\">\n      </div>\n    </div>\n    <div class=\"modal-footer\" style=\"justify-content:space-between\">\n      <button class=\"btn btn-ghost\" id=\"btnDeleteClient\" style=\"color:var(--red);border-color:#FECACA\" onclick=\"deleteCurrentClient()\">Eliminar cliente</button>\n      <div style=\"display:flex;gap:8px\">\n        <button class=\"btn btn-ghost\" onclick=\"closeEdit()\">Cancelar</button>\n        <button class=\"btn btn-primary\" onclick=\"saveEdit()\">Guardar cambios</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Importar clientes ── -->\n<div class=\"modal-overlay\" id=\"importClientesModal\" onclick=\"if(event.target===this)closeImportClientes()\">\n  <div class=\"modal import-modal\">\n    <div class=\"modal-header\">\n      <h2>Importar clientes</h2>\n      <button class=\"modal-close\" onclick=\"closeImportClientes()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n\n      <!-- Paso 1: Subir archivo -->\n      <div id=\"stepUpload\">\n        <div class=\"import-template-bar\">\n          <span>¿Primera vez? Descarga la plantilla oficial con el formato correcto.</span>\n          <button class=\"btn-template\" onclick=\"downloadClientTemplate()\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n            Descargar plantilla\n          </button>\n        </div>\n        <label class=\"import-drop-area\" for=\"importClientesFile\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n          <p>Arrastra tu archivo aquí o <strong>haz clic para seleccionar</strong></p>\n          <p style=\"margin-top:6px;font-size:11.5px\">Excel (.xlsx) o CSV</p>\n        </label>\n        <input type=\"file\" id=\"importClientesFile\" class=\"import-file-input\"\n          accept=\".xlsx,.xls,.csv\" onchange=\"onImportClientesFile(this)\">\n        <div id=\"importClientesError\" style=\"display:none;margin-top:12px;padding:10px 14px;background:var(--red-bg);border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:var(--red)\"></div>\n      </div>\n\n      <!-- Paso 2: Vista previa -->\n      <div id=\"stepPreview\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"previewClientesSummary\"></p>\n        <div class=\"import-preview-wrap\">\n          <div id=\"previewClientesBody\"></div>\n        </div>\n      </div>\n\n      <!-- Paso 3: Duplicados -->\n      <div id=\"stepDuplicates\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"dupClientesSummary\"></p>\n        <div class=\"import-preview-wrap\">\n          <div id=\"dupClientesListBody\"></div>\n        </div>\n        <div class=\"dup-bulk-actions\">\n          <button class=\"btn-dup-cancel\" onclick=\"resolveDuplicate('cancelar')\">Cancelar importación</button>\n          <button class=\"btn-dup-omit-all\" onclick=\"resolveDuplicate('omitir')\">Omitir duplicados e importar el resto</button>\n        </div>\n      </div>\n\n      <!-- Paso 4: Listo -->\n      <div id=\"stepDone\" style=\"display:none\">\n        <div class=\"import-done\">\n          <div class=\"import-done-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n          <p id=\"importDoneMsg\"></p>\n        </div>\n      </div>\n\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeImportClientes()\">Cerrar</button>\n      <button class=\"btn btn-primary\" id=\"btnProcesarImport\"\n        onclick=\"processImportClientes()\"\n        style=\"display:none\">Procesar importación</button>\n    </div>\n  </div>\n</div>\n",
  "registros": "<!-- ── Main: Registros (solo admin) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Registros</h1>\n      <p>Cuentas del equipo — quién tiene acceso y con qué rol</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <button class=\"btn btn-ghost btn-new-item\" onclick=\"openNewVendor()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><line x1=\"19\" y1=\"8\" x2=\"19\" y2=\"14\"/><line x1=\"22\" y1=\"11\" x2=\"16\" y2=\"11\"/></svg>\n        Nueva cuenta\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"table-wrap\">\n      <div class=\"table-footer table-footer-top\">\n        <span class=\"table-footer-text\" id=\"regFooterInfo\">Cargando…</span>\n      </div>\n      <table>\n        <thead>\n          <tr>\n            <th>Nombre</th>\n            <th>Usuario</th>\n            <th class=\"col-city\">Rol</th>\n            <th class=\"col-city\">Estado</th>\n            <th class=\"col-acts\"></th>\n          </tr>\n        </thead>\n        <tbody id=\"regTableBody\"></tbody>\n      </table>\n      <div class=\"empty-state\" id=\"regEmptyState\" style=\"display:none\">\n        <p>Todavía no hay cuentas registradas.</p>\n      </div>\n    </div>\n  </div>\n</main>\n\n<!-- Modal: nueva cuenta -->\n<div class=\"modal-overlay\" id=\"newVendorOverlay\">\n  <div class=\"modal\" style=\"max-width:420px\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Nueva cuenta</h2>\n        <p>Crea una cuenta individual — no se toca la sesión actual</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeNewVendor()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre</label>\n        <input type=\"text\" id=\"newVendorNombre\" class=\"form-input\" placeholder=\"Ej. Ana Torres\" autocomplete=\"off\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Usuario (para iniciar sesión)</label>\n        <input type=\"text\" id=\"newVendorUsuario\" class=\"form-input\" placeholder=\"Ej. ana\" autocomplete=\"off\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Correo <span style=\"font-weight:400;color:var(--text-3)\">(opcional, solo de contacto)</span></label>\n        <input type=\"email\" id=\"newVendorEmail\" class=\"form-input\" placeholder=\"ana@adonay.com\" autocomplete=\"off\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Contraseña temporal</label>\n        <input type=\"text\" id=\"newVendorPassword\" class=\"form-input\" placeholder=\"Mínimo 6 caracteres\" autocomplete=\"off\">\n      </div>\n      <p id=\"newVendorError\" class=\"dcm-subtitle\" style=\"color:var(--red);display:none\"></p>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeNewVendor()\">Cancelar</button>\n      <button class=\"btn btn-primary\" id=\"newVendorSubmit\" onclick=\"submitNewVendor()\">Crear cuenta</button>\n    </div>\n  </div>\n</div>\n",
  "configuracion": "<!-- ── Main: Configuración ── -->\n<main class=\"main\">\n  <div class=\"topbar topbar-hero\">\n    <div class=\"topbar-title\">\n      <h1>Configuración</h1>\n      <p>Personaliza tu sistema y tus preferencias.</p>\n    </div>\n    <!-- Plan de la tienda — mismo patrón que dashPlanTag en\n         dashboard-logic.js (dash-plan-tag + nombrePlan() de\n         plan-limits.js). Vacío hasta que Configuracion.init()\n         corre, para no mostrar un plan incorrecto ni un instante. -->\n    <span class=\"dash-plan-tag\" id=\"configPlanTag\" style=\"display:none\"></span>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"cfg-shell\">\n      <div class=\"cfg-panels\">\n\n        <!-- ── Sección: Inventario ── -->\n        <section class=\"cfg-panel\" id=\"cfgPanelInventario\">\n          <div>\n            <h2 class=\"cfg-panel-title\">Inventario</h2>\n            <p class=\"cfg-panel-desc\">Moneda, umbrales de stock y almacenes.</p>\n          </div>\n\n          <!-- Moneda y formato — tasa de cambio (real) + moneda/formato (aún no configurable) -->\n          <div class=\"cfg-group\" id=\"configCardMoneda\">\n            <div class=\"cfg-group-heading\"><span class=\"cfg-chip-dot blue\"></span>Moneda y formato</div>\n            <div class=\"cfg-card\">\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9.5\"/><path d=\"M12 6.5v11M15 9.2c0-1.2-1.3-2.2-3-2.2s-3 .9-3 2.1c0 3 6 1.4 6 4.4 0 1.2-1.3 2.1-3 2.1s-3-1-3-2.2\"/></svg></span>\n                  <div class=\"cfg-row-text\"><div class=\"cfg-row-label\">Moneda principal</div></div>\n                </div>\n                <div class=\"cfg-row-right\">\n                  <span style=\"font-size:13px;color:var(--text-3);margin-right:6px\">USD - Dólar</span>\n                  <span class=\"settings-soon-tag\">Próximamente</span>\n                </div>\n              </div>\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon\"><svg viewBox=\"0 0 24 24\"><line x1=\"5\" y1=\"9\" x2=\"19\" y2=\"9\"/><line x1=\"5\" y1=\"15\" x2=\"19\" y2=\"15\"/><line x1=\"10\" y1=\"4\" x2=\"8\" y2=\"20\"/><line x1=\"16\" y1=\"4\" x2=\"14\" y2=\"20\"/></svg></span>\n                  <div class=\"cfg-row-text\"><div class=\"cfg-row-label\">Formato de números</div></div>\n                </div>\n                <div class=\"cfg-row-right\">\n                  <span style=\"font-size:13px;color:var(--text-3);margin-right:6px\">1,234.56</span>\n                  <span class=\"settings-soon-tag\">Próximamente</span>\n                </div>\n              </div>\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 7h13M17 7l-3.5-3.5M17 7l-3.5 3.5\"/><path d=\"M20 17H7M7 17l3.5-3.5M7 17l3.5 3.5\"/></svg></span>\n                  <div class=\"cfg-row-text\">\n                    <div class=\"cfg-row-label\">Tasa de cambio</div>\n                    <div class=\"cfg-row-sub\" id=\"tasaCambioSub\">Sin configurar</div>\n                  </div>\n                </div>\n                <div class=\"cfg-row-right\">\n                  <button type=\"button\" class=\"btn btn-primary btn-sm\" onclick=\"toggleCfgEdit('boxTasaCambio')\">Editar</button>\n                </div>\n              </div>\n              <div class=\"cfg-edit-box\" id=\"boxTasaCambio\">\n                <div class=\"settings-row\" style=\"margin-top:6px\">\n                  <span class=\"settings-row-label\">1 USD =</span>\n                  <input class=\"form-input text-mono settings-row-input\" id=\"inputTasaCambio\" type=\"number\" min=\"0\" step=\"0.001\" placeholder=\"3.75\" oninput=\"previsualizarTasaCambio()\">\n                  <span class=\"settings-row-label\">Soles</span>\n                </div>\n                <p class=\"settings-preview\" id=\"tasaCambioPreview\"></p>\n                <div class=\"settings-card-footer\" style=\"margin-top:10px\">\n                  <p id=\"tasaCambioMsg\" class=\"settings-msg\"></p>\n                  <button class=\"btn btn-primary btn-sm\" id=\"btnGuardarTasa\" onclick=\"guardarTasaCambio()\">Guardar</button>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Stock bajo — umbral (real) + alerta en dashboard (visual, aún no conectada) -->\n          <div class=\"cfg-group\" id=\"configCardUmbral\">\n            <div class=\"cfg-group-heading\"><span class=\"cfg-chip-dot amber\"></span>Stock bajo</div>\n            <div class=\"cfg-card\">\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon amber\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2.5 20 6v6c0 5-3.4 8.4-8 9.5-4.6-1.1-8-4.5-8-9.5V6z\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12.5\"/><circle cx=\"12\" cy=\"15.3\" r=\"0.6\" fill=\"currentColor\" stroke=\"none\"/></svg></span>\n                  <div class=\"cfg-row-text\">\n                    <div class=\"cfg-row-label\">Umbral de stock</div>\n                    <div class=\"cfg-row-sub\" id=\"umbralStockSub\">3 unidades o menos</div>\n                  </div>\n                </div>\n                <div class=\"cfg-row-right\">\n                  <button type=\"button\" class=\"btn btn-primary btn-sm\" onclick=\"toggleCfgEdit('boxUmbralStock')\">Editar</button>\n                </div>\n              </div>\n              <div class=\"cfg-edit-box\" id=\"boxUmbralStock\">\n                <div class=\"settings-row\" style=\"margin-top:6px\">\n                  <span class=\"settings-row-label\">Umbral de stock</span>\n                  <div class=\"stepper\">\n                    <button type=\"button\" id=\"btnUmbralMenos\" onclick=\"ajustarUmbralStock(-1)\" aria-label=\"Restar unidad\">−</button>\n                    <input class=\"text-mono\" id=\"inputUmbralStock\" type=\"number\" min=\"0\" step=\"1\" placeholder=\"5\" oninput=\"previsualizarUmbralStock()\">\n                    <button type=\"button\" id=\"btnUmbralMas\" onclick=\"ajustarUmbralStock(1)\" aria-label=\"Sumar unidad\">+</button>\n                  </div>\n                  <span class=\"settings-row-label\">unidades o menos</span>\n                </div>\n                <p class=\"settings-preview\" id=\"umbralStockPreview\"></p>\n                <div class=\"settings-card-footer\" style=\"margin-top:10px\">\n                  <p id=\"umbralStockMsg\" class=\"settings-msg\"></p>\n                  <button class=\"btn btn-primary btn-sm\" id=\"btnGuardarUmbral\" onclick=\"guardarUmbralStock()\">Guardar</button>\n                </div>\n              </div>\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon amber\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 8a6 6 0 0 1 12 0c0 5 2 6 2 6H4s2-1 2-6\"/><path d=\"M10 21a2 2 0 0 0 4 0\"/></svg></span>\n                  <div class=\"cfg-row-text\">\n                    <div class=\"cfg-row-label\">Alerta en el dashboard</div>\n                  </div>\n                </div>\n                <div class=\"cfg-row-right\">\n                  <span class=\"settings-soon-tag\">Próximamente</span>\n                  <button type=\"button\" class=\"toggle-switch active\" id=\"toggleAlertaDashboard\" onclick=\"togglePreviewVisual(this)\" aria-label=\"Mostrar alerta en el dashboard\" title=\"Próximamente\">\n                    <span class=\"toggle-knob\"></span>\n                  </button>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Almacenes (real) -->\n          <div class=\"cfg-group\" id=\"configCardAlmacenes\">\n            <div class=\"cfg-group-heading\"><span class=\"cfg-chip-dot green\"></span>Almacenes</div>\n            <p class=\"cfg-row-sub\" id=\"almacenesPlanNote\" style=\"margin:-4px 0 0\">Nombres de los almacenes que ve el equipo en Catálogo.</p>\n            <div class=\"cfg-card\" id=\"almacenesControl\">\n              <div id=\"almacenesList\"><!-- filas generadas por renderAlmacenesList() en configuracion-logic.js --></div>\n            </div>\n            <div class=\"settings-card-footer\">\n              <p id=\"almacenesMsg\" class=\"settings-msg\"></p>\n              <div style=\"display:flex;gap:8px\">\n                <button type=\"button\" class=\"btn btn-accent-outline btn-sm\" id=\"btnAgregarAlmacen\" onclick=\"agregarAlmacen()\">+ Agregar almacén</button>\n                <button class=\"btn btn-primary btn-sm\" id=\"btnGuardarAlmacenes\" onclick=\"guardarAlmacenesForm()\">Guardar nombres</button>\n              </div>\n            </div>\n          </div>\n\n        </section>\n\n        <!-- ── Panel: Tienda y cuenta ── -->\n        <section class=\"cfg-panel\" id=\"cfgPanelTienda\">\n          <div>\n            <h2 class=\"cfg-panel-title\">Tienda y cuenta</h2>\n            <p class=\"cfg-panel-desc\">Identidad de marca y preferencias del sistema.</p>\n          </div>\n\n          <!-- Logo de la tienda (real) — la fila entera se oculta cuando\n               el plan no lo incluye (ver aplicarBloqueoPorPlan() en\n               configuracion-logic.js): en Básico esta función no existe\n               todavía para la tienda, así que no tiene sentido dejarla\n               visible ocupando espacio. -->\n          <div class=\"cfg-group\" id=\"configCardLogo\">\n            <div class=\"cfg-group-heading\"><span class=\"cfg-chip-dot slate\"></span>Marca</div>\n            <div class=\"cfg-card\">\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon slate\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"/><path d=\"M21 15l-5-5L5 21\"/></svg></span>\n                  <div class=\"cfg-row-text\">\n                    <div class=\"cfg-row-label\">Logo de la tienda</div>\n                    <div class=\"cfg-row-sub\" id=\"logoPlanNote\">Reemplaza el ícono de VAERON en el menú por el logo de tu tienda.</div>\n                  </div>\n                </div>\n                <div class=\"cfg-row-right\" id=\"logoControl\">\n                  <div id=\"logoPreview\" style=\"width:34px;height:34px;border-radius:8px;background:var(--surface-2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;overflow:hidden;flex-shrink:0\">\n                    <span style=\"font-size:8px;color:var(--text-3);text-align:center\">Sin logo</span>\n                  </div>\n                  <label class=\"btn btn-primary btn-sm\" id=\"logoFileLabel\" style=\"cursor:pointer\">\n                    Subir\n                    <input type=\"file\" id=\"logoFile\" accept=\"image/*\" style=\"display:none\" onchange=\"subirLogoTienda(this)\">\n                  </label>\n                </div>\n              </div>\n              <div class=\"cfg-row\" style=\"border-top:1px solid var(--border);padding-top:8px\" id=\"logoMsgRow\">\n                <p id=\"logoMsg\" class=\"settings-msg\" style=\"padding:5px 0\"></p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Preferencias generales — Tema real, Idioma aún no conectado -->\n          <div class=\"cfg-group\">\n            <div class=\"cfg-group-heading\"><span class=\"cfg-chip-dot purple\"></span>Preferencias</div>\n            <div class=\"cfg-card\">\n              <button type=\"button\" class=\"cfg-row\" style=\"width:100%;background:none;border:none;border-bottom:1px solid var(--border);font:inherit;text-align:left;cursor:pointer;color:inherit\" onclick=\"toggleTema()\">\n                <span class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon purple\"><svg viewBox=\"0 0 24 24\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg></span>\n                  <span class=\"cfg-row-text\"><span class=\"cfg-row-label\">Tema</span></span>\n                </span>\n                <span class=\"cfg-row-right\" style=\"color:var(--text-3);font-size:13px\" id=\"temaValLabel\">Claro\n                  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"9 6 15 12 9 18\"/></svg>\n                </span>\n              </button>\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon purple\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9.5\"/><line x1=\"2.5\" y1=\"12\" x2=\"21.5\" y2=\"12\"/><path d=\"M12 2.5c2.6 2.6 4 6 4 9.5s-1.4 6.9-4 9.5c-2.6-2.6-4-6-4-9.5s1.4-6.9 4-9.5z\"/></svg></span>\n                  <div class=\"cfg-row-text\"><div class=\"cfg-row-label\">Idioma</div></div>\n                </div>\n                <div class=\"cfg-row-right\">\n                  <span style=\"font-size:13px;color:var(--text-3)\">Español</span>\n                  <span class=\"settings-soon-tag\">Próximamente</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Soporte y ayuda — visual, aún no conectada -->\n          <div class=\"cfg-group\">\n            <div class=\"cfg-group-heading\"><span class=\"cfg-chip-dot slate\"></span>Soporte</div>\n            <div class=\"cfg-card\">\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon slate\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 18v-6a9 9 0 0 1 18 0v6\"/><path d=\"M21 19a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2h3z\"/><path d=\"M3 19a2 2 0 0 0 2 2h1a2 2 0 0 0 2-2v-3a2 2 0 0 0-2-2H3z\"/></svg></span>\n                  <div class=\"cfg-row-text\"><div class=\"cfg-row-label\">Centro de ayuda</div></div>\n                </div>\n                <div class=\"cfg-row-right\"><span class=\"settings-soon-tag\">Próximamente</span></div>\n              </div>\n              <div class=\"cfg-row\">\n                <div class=\"cfg-row-left\">\n                  <span class=\"cfg-row-icon slate\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m2 7 10 6 10-6\"/></svg></span>\n                  <div class=\"cfg-row-text\"><div class=\"cfg-row-label\">Contactar soporte</div></div>\n                </div>\n                <div class=\"cfg-row-right\"><span class=\"settings-soon-tag\">Próximamente</span></div>\n              </div>\n            </div>\n          </div>\n\n        </section>\n\n      </div>\n    </div>\n  </div>\n</main>\n",
  "config-sistema": "<!-- ── Main: Configuración del sistema (solo súper-admin) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Configuración</h1>\n      <p>Preferencias generales del sistema</p>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"settings-grid\">\n\n      <!-- 1. Cuenta y seguridad — real: correo de la cuenta + acceso directo\n           a Perfil, que ya tiene nombre/contraseña conectados de verdad\n           (ver perfil-logic.js). No se duplica esa lógica acá. -->\n      <div class=\"settings-card\" id=\"configCardCuenta\">\n        <div class=\"settings-card-head\">\n          <div class=\"settings-card-icon\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>\n          </div>\n          <div class=\"settings-card-head-text\">\n            <h3>Cuenta y seguridad</h3>\n            <p>Datos de acceso de tu cuenta de súper-admin.</p>\n          </div>\n        </div>\n        <div class=\"settings-card-control\">\n          <div class=\"settings-static-row\">\n            <span>Correo de acceso</span>\n            <span class=\"settings-static-val\" id=\"configSistemaCorreo\">—</span>\n          </div>\n          <button type=\"button\" class=\"settings-static-row settings-static-row-clickable\" onclick=\"Router.go('perfil')\">\n            <span class=\"settings-static-row-icon\">\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\n              Nombre y contraseña\n            </span>\n            <span class=\"settings-static-val\">Ir a Perfil\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"9 6 15 12 9 18\"/></svg>\n            </span>\n          </button>\n        </div>\n      </div>\n\n      <!-- 2. Capacidad de los proyectos — real: cuántas tiendas tiene cada\n           proyecto Firebase configurado, sobre el máximo permitido (mismo\n           dato que usa elegirProyectoConEspacio() para decidir dónde crear\n           la próxima tienda — ver firebase-projects.js). Solo lectura. -->\n      <div class=\"settings-card\" id=\"configCardProyectos\">\n        <div class=\"settings-card-head\">\n          <div class=\"settings-card-icon ic-slate\">\n            <svg viewBox=\"0 0 24 24\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M3 5v14c0 1.66 4.03 3 9 3s9-1.34 9-3V5\"/><path d=\"M3 12c0 1.66 4.03 3 9 3s9-1.34 9-3\"/></svg>\n          </div>\n          <div class=\"settings-card-head-text\">\n            <h3>Capacidad de los proyectos</h3>\n            <p>Cuántas tiendas tiene cada proyecto Firebase, sobre el máximo permitido.</p>\n          </div>\n        </div>\n        <div class=\"settings-card-control\" id=\"configSistemaProyectosList\">\n          <p class=\"settings-msg\">Cargando…</p>\n        </div>\n      </div>\n\n      <!-- 3. Almacenes -->\n      <div class=\"settings-card\" id=\"configCardAlmacenes\">\n        <div class=\"settings-card-head\">\n          <div class=\"settings-card-icon\">\n            <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"3\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"9\" y=\"3\" width=\"13\" height=\"2\" rx=\"1\"/><rect x=\"9\" y=\"7\" width=\"8\" height=\"2\" rx=\"1\"/><rect x=\"2\" y=\"11\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"9\" y=\"11\" width=\"13\" height=\"2\" rx=\"1\"/><rect x=\"9\" y=\"15\" width=\"8\" height=\"2\" rx=\"1\"/></svg>\n          </div>\n          <div class=\"settings-card-head-text\">\n            <h3>Almacenes</h3>\n            <p>Se administra desde la Configuración de cada tienda, no aquí.</p>\n          </div>\n        </div>\n        <div class=\"settings-card-control\">\n          <button type=\"button\" class=\"settings-static-row settings-static-row-clickable\" onclick=\"Router.go('tiendas')\">\n            <span>Ver tiendas</span>\n            <span class=\"settings-static-val\">\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"9 6 15 12 9 18\"/></svg>\n            </span>\n          </button>\n        </div>\n      </div>\n\n      <!-- 4. Notificaciones -->\n      <div class=\"settings-card\" id=\"configCardNotificaciones\">\n        <div class=\"settings-card-head\">\n          <div class=\"settings-card-icon\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/><path d=\"M13.73 21a2 2 0 0 1-3.46 0\"/></svg>\n          </div>\n          <div class=\"settings-card-head-text\">\n            <h3>Notificaciones</h3>\n            <p>Se administra desde la Configuración de cada tienda, no aquí.</p>\n          </div>\n        </div>\n        <div class=\"settings-card-control\">\n          <button type=\"button\" class=\"settings-static-row settings-static-row-clickable\" onclick=\"Router.go('tiendas')\">\n            <span>Ver tiendas</span>\n            <span class=\"settings-static-val\">\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"9 6 15 12 9 18\"/></svg>\n            </span>\n          </button>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</main>\n",
  "perfil": "<!-- ── Main: Perfil ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Perfil</h1>\n      <p>Ver y editar tu cuenta</p>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"profile-header\">\n      <div class=\"profile-card\">\n        <div class=\"profile-avatar\" id=\"profileAvatar\">--</div>\n        <div class=\"profile-info\">\n          <div class=\"profile-name\" id=\"profileName\">Cargando…</div>\n          <div class=\"profile-meta\">\n            <span class=\"profile-email\" id=\"profileEmail\"></span>\n            <span class=\"profile-role-badge\" id=\"profileRoleBadge\">—</span>\n          </div>\n          <div id=\"profileSince\" class=\"profile-since\"></div>\n        </div>\n      </div>\n\n      <div class=\"profile-actions-panel\">\n        <button class=\"btn btn-ghost\" id=\"btnSwitchAccountProfile\" onclick=\"switchAccount()\">\n          <svg viewBox=\"0 0 24 24\"><polyline points=\"17 1 21 5 17 9\"/><path d=\"M3 11V9a4 4 0 0 1 4-4h14\"/><polyline points=\"7 23 3 19 7 15\"/><path d=\"M21 13v2a4 4 0 0 1-4 4H3\"/></svg>\n          Cambiar de cuenta\n        </button>\n        <button class=\"btn btn-ghost\" id=\"btnLogoutProfile\" style=\"color:var(--red);border-color:#FECACA\" onclick=\"logout()\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\n          Cerrar sesión\n        </button>\n      </div>\n    </div>\n\n    <div class=\"profile-grid\">\n      <div class=\"settings-card\" id=\"configCardNombre\">\n        <div class=\"settings-card-head\">\n          <div class=\"settings-card-icon\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>\n          </div>\n          <div class=\"settings-card-head-text\">\n            <h3>Nombre para mostrar</h3>\n            <p>Así apareces en el sistema y en el registro de actividad.</p>\n          </div>\n        </div>\n        <div class=\"settings-card-control\">\n          <div class=\"settings-field\">\n            <div style=\"display:flex;gap:8px;width:100%\">\n              <input class=\"form-input\" id=\"editNombreInput\" type=\"text\" maxlength=\"40\" style=\"flex:1\" oninput=\"actualizarContadorNombre()\">\n              <button class=\"btn btn-primary btn-sm\" id=\"btnGuardarNombre\" onclick=\"guardarNombrePerfil()\">Guardar</button>\n            </div>\n            <span class=\"settings-field-hint\" id=\"nombreContador\"></span>\n          </div>\n        </div>\n        <div class=\"settings-card-footer\">\n          <p id=\"nombreMsg\" class=\"settings-msg\"></p>\n        </div>\n      </div>\n\n      <div class=\"settings-card settings-copper\" id=\"configCardPassword\">\n        <div class=\"settings-card-head\">\n          <div class=\"settings-card-icon ic-copper\">\n            <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\n          </div>\n          <div class=\"settings-card-head-text\">\n            <h3>Cambiar contraseña</h3>\n            <p>Necesitas tu contraseña actual para confirmar el cambio.</p>\n          </div>\n        </div>\n        <div class=\"settings-card-control\" style=\"display:flex;flex-direction:column;gap:10px\">\n          <div class=\"form-group\" style=\"width:100%;margin-bottom:0\">\n            <label class=\"form-label\">Contraseña actual</label>\n            <input class=\"form-input\" id=\"pwActual\" type=\"password\" autocomplete=\"current-password\">\n          </div>\n          <div class=\"settings-field\">\n            <label class=\"form-label\">Nueva contraseña</label>\n            <input class=\"form-input\" id=\"pwNueva\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Mínimo 6 caracteres\" oninput=\"evaluarFuerzaPassword()\">\n            <div class=\"pw-strength-track\"><div class=\"pw-strength-fill\" id=\"pwStrengthFill\"></div></div>\n            <span class=\"settings-field-hint\" id=\"pwStrengthLabel\"></span>\n          </div>\n          <div class=\"settings-field\">\n            <label class=\"form-label\">Confirmar nueva contraseña</label>\n            <input class=\"form-input\" id=\"pwConfirmar\" type=\"password\" autocomplete=\"new-password\" oninput=\"evaluarFuerzaPassword()\">\n            <span class=\"settings-field-hint\" id=\"pwMatchHint\"></span>\n          </div>\n        </div>\n        <div class=\"settings-card-footer\">\n          <p id=\"pwMsg\" class=\"settings-msg\"></p>\n          <button class=\"btn btn-primary btn-sm\" id=\"btnCambiarPassword\" onclick=\"cambiarPasswordPerfil()\">Cambiar contraseña</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</main>\n",
  "tiendas": "<!-- ── Main: Tiendas (solo súper-admin) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Tiendas</h1>\n      <p>Cuentas del sistema — una por cliente</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <button class=\"btn btn-primary btn-new-item\" onclick=\"openModal('tiendaModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\n        Nueva tienda\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n\n    <div class=\"stock-stats\" id=\"tiendaStatsRow\">\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Tiendas registradas</div>\n        <div class=\"stat-value\" id=\"statTiendaTotal\">—</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Activas</div>\n        <div class=\"stat-value\" style=\"color:#047857\" id=\"statTiendaActivas\">—</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Suspendidas</div>\n        <div class=\"stat-value\" style=\"color:var(--red)\" id=\"statTiendaSuspendidas\">—</div>\n      </div>\n    </div>\n\n    <div class=\"product-table-wrap simple-table-wrap\">\n      <table class=\"product-table\">\n        <thead>\n          <tr>\n            <th>Tienda</th>\n            <th>Contacto</th>\n            <th>Usuarios</th>\n            <th>Alta</th>\n            <th>Estado</th>\n            <th></th>\n          </tr>\n        </thead>\n        <tbody id=\"tiendaTableBody\"></tbody>\n      </table>\n    </div>\n\n    <div class=\"empty-state\" id=\"tiendaEmptyState\" style=\"display:none\">\n      <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/></svg>\n      <p>Todavía no registraste ninguna tienda.</p>\n    </div>\n\n  </div>\n</main>\n\n<!-- ── Modal: Nueva tienda ── -->\n<div class=\"modal-overlay\" id=\"tiendaModal\" onclick=\"outsideClose(event,'tiendaModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Nueva tienda</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\">Crea la cuenta y su primer usuario admin</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('tiendaModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre de la tienda / empresa</label>\n        <input class=\"form-input\" id=\"tiendaNombre\" type=\"text\" placeholder=\"Ej: Guitarrería Central\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre del administrador</label>\n        <input class=\"form-input\" id=\"tiendaAdminNombre\" type=\"text\" placeholder=\"Ej: Carlos Pérez\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Correo del administrador</label>\n        <input class=\"form-input\" id=\"tiendaAdminCorreo\" type=\"email\" placeholder=\"carlos@guitarreriacentral.com\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Contraseña inicial</label>\n        <input class=\"form-input text-mono\" id=\"tiendaAdminPassword\" type=\"text\" placeholder=\"Mínimo 6 caracteres\">\n      </div>\n      <div id=\"tiendaError\" style=\"display:none;margin-top:4px;padding:10px 14px;background:var(--red-bg);border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:var(--red)\"></div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('tiendaModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" id=\"btnCrearTienda\" onclick=\"crearTiendaDesdeForm()\">Crear tienda</button>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Editar tienda ── -->\n<div class=\"modal-overlay\" id=\"tiendaEditModal\" onclick=\"outsideClose(event,'tiendaEditModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Editar tienda</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\">Datos de contacto y del administrador</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('tiendaEditModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre de la tienda / empresa</label>\n        <input class=\"form-input\" id=\"editTiendaNombre\" type=\"text\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Teléfono</label>\n        <input class=\"form-input\" id=\"editTiendaTelefono\" type=\"text\" placeholder=\"Ej: 987 654 321\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Ciudad</label>\n        <input class=\"form-input\" id=\"editTiendaCiudad\" type=\"text\" placeholder=\"Ej: Lima\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Dirección</label>\n        <input class=\"form-input\" id=\"editTiendaDireccion\" type=\"text\" placeholder=\"Ej: Av. Los Músicos 123\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre del administrador</label>\n        <input class=\"form-input\" id=\"editTiendaAdminNombre\" type=\"text\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Correo del administrador</label>\n        <input class=\"form-input\" id=\"editTiendaAdminCorreo\" type=\"email\" disabled style=\"opacity:.6;cursor:not-allowed\">\n        <p style=\"font-size:11.5px;color:var(--text-3);margin-top:4px\">\n          El correo de acceso no se puede cambiar desde acá — Firebase solo permite que el propio dueño de la cuenta lo cambie. Si necesita otro correo, hay que crear la cuenta de nuevo.\n        </p>\n      </div>\n      <div id=\"tiendaEditError\" style=\"display:none;margin-top:4px;padding:10px 14px;background:var(--red-bg);border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:var(--red)\"></div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('tiendaEditModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" id=\"btnGuardarEdicionTienda\" onclick=\"guardarEdicionTienda()\">Guardar cambios</button>\n    </div>\n  </div>\n</div>\n",
  "facturacion": "<!-- ── Main: Facturación (solo súper-admin) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Facturación</h1>\n      <p>Plan, monto mensual y estado de pago de cada tienda</p>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n\n    <div class=\"stock-stats\" id=\"factStatsRow\">\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Ingreso mensual estimado</div>\n        <div class=\"stat-value\" id=\"statFactIngreso\">—</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Al día</div>\n        <div class=\"stat-value\" style=\"color:#047857\" id=\"statFactAlDia\">—</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Pendientes / vencidas</div>\n        <div class=\"stat-value\" style=\"color:var(--red)\" id=\"statFactPendientes\">—</div>\n      </div>\n    </div>\n\n    <div class=\"product-table-wrap simple-table-wrap\">\n      <table class=\"product-table\">\n        <thead>\n          <tr>\n            <th>Tienda</th>\n            <th>Plan</th>\n            <th>Monto mensual</th>\n            <th>Próximo cobro</th>\n            <th>Estado de pago</th>\n            <th></th>\n          </tr>\n        </thead>\n        <tbody id=\"facturacionTableBody\"></tbody>\n      </table>\n    </div>\n\n    <div class=\"empty-state\" id=\"facturacionEmptyState\" style=\"display:none\">\n      <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><line x1=\"2\" y1=\"10\" x2=\"22\" y2=\"10\"/></svg>\n      <p>Todavía no hay tiendas registradas.</p>\n    </div>\n\n  </div>\n</main>\n\n<!-- ── Modal: Editar facturación de una tienda ── -->\n<div class=\"modal-overlay\" id=\"facturacionModal\" onclick=\"outsideClose(event,'facturacionModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Editar facturación</h2>\n        <p id=\"facturacionModalTienda\" style=\"font-size:12px;color:var(--text-3);margin-top:2px\"></p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('facturacionModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Plan</label>\n        <select class=\"form-input\" id=\"facturacionPlan\">\n          <option value=\"basico\">Básico</option>\n          <option value=\"medio\">Medio</option>\n          <option value=\"premium\">Premium</option>\n        </select>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Monto mensual (S/)</label>\n        <input class=\"form-input text-mono\" id=\"facturacionMonto\" type=\"number\" min=\"0\" step=\"0.01\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Próximo cobro</label>\n        <input class=\"form-input\" id=\"facturacionProximoCobro\" type=\"date\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Estado de pago</label>\n        <select class=\"form-input\" id=\"facturacionEstadoPago\">\n          <option value=\"al_dia\">Al día</option>\n          <option value=\"pendiente\">Pendiente</option>\n          <option value=\"vencido\">Vencido</option>\n        </select>\n      </div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('facturacionModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" onclick=\"guardarFacturacionDesdeForm()\">Guardar cambios</button>\n    </div>\n  </div>\n</div>\n",
  "auditoria": "<!-- ── Main: Auditoría (solo súper-admin) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Auditoría</h1>\n      <p>Registro de acciones administrativas — quién hizo qué y cuándo</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <button class=\"btn btn-ghost\" onclick=\"Auditoria.init()\">\n        <svg viewBox=\"0 0 24 24\"><polyline points=\"23 4 23 10 17 10\"/><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"/></svg>\n        Actualizar\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n\n    <div class=\"product-table-wrap simple-table-wrap\">\n      <table class=\"product-table\">\n        <thead>\n          <tr>\n            <th>Fecha</th>\n            <th>Evento</th>\n            <th>Detalle</th>\n            <th>Tienda</th>\n            <th>Realizado por</th>\n          </tr>\n        </thead>\n        <tbody id=\"auditoriaTableBody\"></tbody>\n      </table>\n    </div>\n\n    <div class=\"empty-state\" id=\"auditoriaEmptyState\" style=\"display:none\">\n      <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><path d=\"M9 11l3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n      <p>Todavía no hay eventos registrados.</p>\n    </div>\n\n  </div>\n</main>\n"
};;;;;;

window.Router = (function() {
  const VIEWS = {
    dashboard:    { init: () => window.Dashboard   && Dashboard.init() },
    stock:        { init: () => window.Stock       && Stock.init() },
    catalogo:     { init: () => window.Catalogo    && Catalogo.init() },
    foro:         { init: () => window.Foro        && Foro.init() },
    pedidos:      { init: () => window.Pedidos     && Pedidos.init() },
    registros:    { init: () => window.Registros   && Registros.init() },
    configuracion: { init: () => window.Configuracion && Configuracion.init() },
    perfil:        { init: () => window.Perfil        && Perfil.init() },
    tiendas:       { init: () => window.Tiendas       && Tiendas.init() },
    facturacion:   { init: () => window.Facturacion   && Facturacion.init() },
    auditoria:     { init: () => window.Auditoria     && Auditoria.init() },
    'config-sistema': { init: () => window.ConfigSistema && ConfigSistema.init() }
  };

  let currentPage = null;

  function setActiveNavItem(page) {
    document.querySelectorAll('.nav-item[data-page]').forEach(el => {
      el.classList.toggle('active', el.dataset.page === page);
    });
  }

  function go(page, opts) {
    opts = opts || {};
    const view = VIEWS[page];
    const html = VIEWS_HTML[page];

    if (!view || !html) {
      console.error('[Router] Página desconocida:', page);
      return;
    }

    if (page === currentPage && !opts.force) return;

    const root = document.getElementById('viewRoot');

    try {
      root.innerHTML = html;
      currentPage = page;
      setActiveNavItem(page);
      if (!opts.skipHistory) {
        history.pushState({ page }, '', '#' + page);
      }
      view.init(opts.params);
    } catch (err) {
      console.error('[Router] Error al mostrar la vista', page, err);
      root.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-3)">' +
        'Ocurrió un error al mostrar esta sección. <a href="#" onclick="Router.go(\'' + page + '\',{force:true});return false;">Reintentar</a>' +
        '</div>';
    }
  }

  function start() {
    const initialPage = (window.location.hash || '#stock').slice(1);
    go(initialPage, { skipHistory: true });

    window.addEventListener('popstate', e => {
      const page = (e.state && e.state.page) || (window.location.hash || '#stock').slice(1);
      go(page, { skipHistory: true });
    });
  }

  return { go, start, get currentPage() { return currentPage; } };
})();